		if (!validation.isValid) {
			$.set(error, validation.error, true);
			return;
		}

		let npub = "";
		let privateKey;

		try {
			const { type, data } = nip19.decode($.get(nsec));

			if (type !== "nsec") {
				$.set(error, "Invalid nsec format");
				return;
			}

			privateKey = data;
			npub = getPublicKey(data);
		} catch(err) {
			$.set(error, "Invalid private key");
			return;
