		if (!npub) {
			$.set(error, "Invalid private key");
			return;
		}

		const event = {
			kind: 22242,
			created_at: Math.floor(Date.now() / 1000),
			content: challenge,
			tags: [
				["relay", window.location.origin],
				["challenge", challenge]
			],
			pubkey: npub
		};

		const signedEvent = finalizeEvent(event, privateKey);

		if (!validateEvent(signedEvent)) {
			throw new Error("Invalid event");
		}

		let deviceId = await getDeviceIdentifier();
		let { encrypted, salt, exportedKey, iterations } = await encryptNsec($.get(nsec), deviceId);

		const res = await authService.loginWithNostr({
			event: signedEvent,
			challenge,
			encryptedPrivateKey: encrypted.data,
			iv: encrypted.iv,
			authTag: encrypted.authTag,
			salt,
			iterations,
			authMethod: "passkey",
			deviceId
		});

		if (res.access_token) {
			const deviceName = await createUserDeviceShortName(npub);
			let credentialId = "";

			if (res.isNewUser) {
				if (authMethods.biometric) {
					credentialId = await setBiometricKey(npub, exportedKey, "biometrics", deviceName);
				} else {
					credentialId = await setWebBiometricKey(npub, exportedKey, deviceName);
				}
			} else {
				deviceId = res.user.nostrKey?.deviceId;
				({ encrypted, salt, exportedKey, iterations } = await encryptNsec($.get(nsec), deviceId, 100000, res.user.nostrKey?.salt));

				const deviceName = await createUserDeviceShortName(npub);

				if (authMethods.biometric) {
					credentialId = await setBiometricKey(npub, exportedKey, "biometrics", deviceName);
				} else {
					credentialId = await setWebBiometricKey(npub, exportedKey, deviceName);
				}
			}

			if (!credentialId) throw new Error("Failed to set biometric key");
			await authService.registerPasskeyDevice(npub, deviceId, deviceName, credentialId);

			const biometricData = {
				username: npub,
				password: JSON.stringify({
					key: exportedKey,
					data: encrypted.data,
					iv: encrypted.iv,
					authTag: encrypted.authTag,
					salt
				}),
				server: deviceId
			};

			authState.setupAuthData(res.access_token, "nsec", npub, res.user, biometricData, false).then(() => {
				if (res.isNewUser) goto("/auth/onboarding"); else goto("/dashboard/find-tasks");
			});
		}
